From b5d5d7d33219225e050cc59b1785f2b6f40e8bd9 Mon Sep 17 00:00:00 2001
From: Alex Wang <alexw@nicira.com>
Date: Mon, 12 Aug 2013 14:14:52 -0700
Subject: [PATCH] band: Fix error in bond_choose_output_slave() function.

This commit fixes the error introduced by commit 4a1b8f30e59 (bond:
Stop using tags.). The error is caused by mistakenly returning 'slave'
where 'slave->aux' should be returned.

Signed-off-by: Alex Wang <alexw@nicira.com>
Signed-off-by: Ben Pfaff <blp@nicira.com>

diff --git a/lib/bond.c b/lib/bond.c
index a9278db84..3834774d4 100644
--- a/lib/bond.c
+++ b/lib/bond.c
@@ -661,11 +661,14 @@ bond_choose_output_slave(struct bond *bond, const struct flow *flow,
                          struct flow_wildcards *wc, uint16_t vlan)
 {
     struct bond_slave *slave;
+    void *aux;

     ovs_rwlock_rdlock(&rwlock);
     slave = choose_output_slave(bond, flow, wc, vlan);
+    aux = slave ? slave->aux : NULL;
     ovs_rwlock_unlock(&rwlock);
-    return slave;
+
+    return aux;
 }

 /* Rebalancing. */
-- 
2.25.1

Code statements:
```c
-    return slave;
+    return aux;
```

Code statements:
```c
-    return slave;
+    return aux;
```

The code statements that lead to the bug are:
```c
slave = choose_output_slave(bond, flow, wc, vlan);
return slave;
```
Reason:
The function `bond_choose_output_slave()` mistakenly returns the `slave` object instead of the auxiliary data `slave->aux`. This was a result of changes made in a previous commit that stopped using tags, leading to incorrect behavior when the function was expected to return the auxiliary data associated with the selected slave.

The code statements that fix the bug are:
```c
void *aux;
aux = slave ? slave->aux : NULL;
return aux;
```
Reason:
The patch introduces a new variable `aux` that correctly retrieves the auxiliary data from the `slave` object. By returning `aux` instead of `slave`, the function now provides the expected auxiliary data, thus fixing the error introduced in the previous commit.

